package com.rekluzlabs.makokolorize.ui.screensimport android.content.Intentimport android.graphics.Bitmapimport android.graphics.BitmapFactoryimport android.net.Uriimport android.util.Logimport androidx.activity.compose.rememberLauncherForActivityResultimport androidx.activity.result.contract.ActivityResultContractsimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.navigationBarsPaddingimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material3.AlertDialogimport androidx.compose.material3.Buttonimport androidx.compose.material3.ExperimentalMaterial3Apiimport androidx.compose.material3.FilterChipimport androidx.compose.material3.HorizontalDividerimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.OutlinedButtonimport androidx.compose.material3.Sliderimport androidx.compose.material3.SliderDefaultsimport androidx.compose.material3.Textimport androidx.compose.material3.TextButtonimport androidx.compose.runtime.Composableimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableFloatStateOfimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.rememberCoroutineScopeimport androidx.compose.runtime.setValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.platform.LocalContextimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.text.style.TextAlignimport androidx.compose.ui.unit.dpimport androidx.compose.ui.unit.spimport androidx.core.content.FileProviderimport com.rekluzlabs.makokolorize.ui.components.ImageComparisonimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.launchimport kotlinx.coroutines.withContextimport java.io.File@OptIn(ExperimentalMaterial3Api::class)@Composablefun ResultScreen(    originalUri: Uri,    resultUri: Uri,    onBack: () -> Unit,    onReRun: () -> Unit) {    val context = LocalContext.current    val scope = rememberCoroutineScope()    var showSaveDialog by remember { mutableStateOf(false) }    var saveSuccess by remember { mutableStateOf<String?>(null) }    var saveQuality by remember { mutableFloatStateOf(95f) }    var selectedFormat by remember { mutableStateOf(Bitmap.CompressFormat.JPEG) }    fun saveBitmap(targetUri: Uri, format: Bitmap.CompressFormat, quality: Int) {        scope.launch {            saveSuccess = try {                withContext(Dispatchers.IO) {                    val input = context.contentResolver.openInputStream(resultUri)                        ?: return@withContext "Could not read result"                    val bmp = BitmapFactory.decodeStream(input)                    input.close()                    if (bmp == null) return@withContext "Failed to decode result"                    val out = context.contentResolver.openOutputStream(targetUri)                        ?: return@withContext "Could not write to that location"                    out.use { stream ->                        if (!bmp.compress(format, quality, stream)) {                            return@use "Failed to save image"                        }                    }                    bmp.recycle()                    null                }            } catch (e: Exception) {                Log.e("ResultScreen", "Save failed", e)                "Save failed: ${e.localizedMessage ?: "Unknown error"}"            }        }    }    fun shareBitmap() {        scope.launch {            try {                val shareUri = FileProvider.getUriForFile(                    context,                    "${context.packageName}.fileprovider",                    File(resultUri.path!!)                )                val intent = Intent(Intent.ACTION_SEND).apply {                    type = "image/png"                    putExtra(Intent.EXTRA_STREAM, shareUri)                    addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)                }                context.startActivity(Intent.createChooser(intent, "Share"))            } catch (e: Exception) {                Log.e("ResultScreen", "Share failed", e)            }        }    }    val jpegLauncher = rememberLauncherForActivityResult(        contract = ActivityResultContracts.CreateDocument("image/jpeg")    ) { uri ->        if (uri != null) saveBitmap(uri, Bitmap.CompressFormat.JPEG, saveQuality.toInt())    }    val pngLauncher = rememberLauncherForActivityResult(        contract = ActivityResultContracts.CreateDocument("image/png")    ) { uri ->        if (uri != null) saveBitmap(uri, Bitmap.CompressFormat.PNG, 100)    }    Column(modifier = Modifier.fillMaxSize()) {        // Before/After comparison fills available space        Box(modifier = Modifier.weight(1f)) {            ImageComparison(                beforeUri = originalUri,                afterUri = resultUri,                modifier = Modifier.fillMaxSize()            )        }        // Bottom action bar        Column(            modifier = Modifier.navigationBarsPadding()        ) {            saveSuccess?.let { msg ->                val isError = msg.startsWith("Save failed") || msg.startsWith("Could not") || msg.startsWith("Failed")                Text(                    msg,                    color = if (isError) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary,                    textAlign = TextAlign.Center,                    modifier = Modifier                        .fillMaxWidth()                        .padding(horizontal = 16.dp, vertical = 4.dp),                    fontSize = 13.sp                )            }            HorizontalDivider()            Row(                modifier = Modifier                    .fillMaxWidth()                    .padding(horizontal = 16.dp, vertical = 12.dp),                horizontalArrangement = Arrangement.spacedBy(12.dp)            ) {                OutlinedButton(                    onClick = onBack,                    modifier = Modifier.weight(1f)                ) {                    Text("\u2190 Back")                }                Button(                    onClick = { showSaveDialog = true },                    modifier = Modifier.weight(1f)                ) {                    Text("Save")                }                Button(                    onClick = { shareBitmap() },                    modifier = Modifier.weight(1f)                ) {                    Text("Share")                }            }        }    }    if (showSaveDialog) {        AlertDialog(            onDismissRequest = { showSaveDialog = false },            title = { Text("Save Image") },            text = {                Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {                    Text("Choose image format and quality:")                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {                        FilterChip(                            selected = selectedFormat == Bitmap.CompressFormat.JPEG,                            onClick = { selectedFormat = Bitmap.CompressFormat.JPEG },                            label = { Text("JPEG") }                        )                        FilterChip(                            selected = selectedFormat == Bitmap.CompressFormat.PNG,                            onClick = { selectedFormat = Bitmap.CompressFormat.PNG },                            label = { Text("PNG") }                        )                    }                    if (selectedFormat == Bitmap.CompressFormat.JPEG) {                        Column {                            val qualityLabel = when {                                saveQuality < 40 -> "Low"                                saveQuality < 80 -> "Balanced"                                else -> "High"                            }                            Text(                                text = "Quality: ${saveQuality.toInt()}% ($qualityLabel)",                                fontSize = 14.sp,                                fontWeight = FontWeight.Medium,                                color = MaterialTheme.colorScheme.onSurfaceVariant                            )                            Slider(                                value = saveQuality,                                onValueChange = { saveQuality = it },                                valueRange = 1f..100f,                                steps = 99,                                colors = SliderDefaults.colors(                                    thumbColor = MaterialTheme.colorScheme.primary,                                    activeTrackColor = MaterialTheme.colorScheme.primary                                )                            )                        }                    } else {                        Text(                            text = "PNG is lossless (maximum quality)",                            fontSize = 12.sp,                            color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f)                        )                    }                }            },            confirmButton = {                Button(onClick = {                    showSaveDialog = false                    if (selectedFormat == Bitmap.CompressFormat.JPEG) {                        jpegLauncher.launch("colorized_${System.currentTimeMillis()}.jpg")                    } else {                        pngLauncher.launch("colorized_${System.currentTimeMillis()}.png")                    }                }) {                    Text("Save")                }            },            dismissButton = {                TextButton(onClick = { showSaveDialog = false }) {                    Text("Cancel")                }            }        )    }}